bash -c 'cat > /tmp/calculate_metrics.js << "EOF"
const fs = require("fs");
const traces = JSON.parse(fs.readFileSync("/tmp/traces.json", "utf8"));
const thompson = JSON.parse(fs.readFileSync("/tmp/thompson.json", "utf8"));

// Calculate goal achievement rate
const goalAchieved = traces.filter(t => t.outcome === "success").length;
const goalAchievementRate = traces.length > 0 ? (goalAchieved / traces.length) : 0;

// Calculate template hit rate (activities that had alpha > 0)
const templatesWithHistory = thompson.templates.filter(t => t.alpha > 0).length;
const templateHitRate = thompson.templates.length > 0 ? (templatesWithHistory / thompson.templates.length) : 0;

// Calculate improvisation conversion (traces without template that succeeded)
const improvisedTraces = traces.filter(t => !t.templateId || t.templateId.includes("improvised"));
const successfulImprovisations = improvisedTraces.filter(t => t.outcome === "success").length;
const improvisationConversionRate = improvisedTraces.length > 0 ? (successfulImprovisations / improvisedTraces.length) : 0;

// Calculate average rank of successful activities
const successfulWithRank = traces.filter(t => t.outcome === "success" && t.thompsonRank);
const avgRank = successfulWithRank.length > 0 
  ? successfulWithRank.reduce((sum, t) => sum + t.thompsonRank, 0) / successfulWithRank.length 
  : 0;

const metrics = {
  timestamp: new Date().toISOString(),
  lookbackHours: {{lookbackHours}},
  totalTraces: traces.length,
  goalAchievementRate,
  templateHitRate,
  improvisationConversionRate,
  avgSuccessfulRank: avgRank,
  thompsonSamplingStats: {
    totalTemplates: thompson.templates.length,
    templatesWithHistory,
    avgAlpha: thompson.templates.reduce((sum, t) => sum + (t.alpha || 0), 0) / thompson.templates.length,
    avgBeta: thompson.templates.reduce((sum, t) => sum + (t.beta || 0), 0) / thompson.templates.length
  },
  traces: traces.slice(0, 20).map(t => ({
    executionId: t.executionId,
    templateId: t.templateId,
    outcome: t.outcome,
    duration: t.duration,
    cost: t.cost,
    timestamp: t.timestamp
  }))
};

fs.writeFileSync("/tmp/metrics.json", JSON.stringify(metrics, null, 2));
console.log(JSON.stringify(metrics, null, 2));
EOF
node /tmp/calculate_metrics.js'

bash -c 'cat > /tmp/generate_index.js << "EOF"
const fs = require("fs");
const traces = JSON.parse(fs.readFileSync("/tmp/traces.json", "utf8"));

const index = {
  timestamp: new Date().toISOString(),
  totalTraces: traces.length,
  traces: traces.map(t => ({
    id: t.executionId,
    templateId: t.templateId,
    outcome: t.outcome,
    duration: t.duration,
    cost: t.cost,
    timestamp: t.timestamp,
    category: t.category,
    tags: t.tags
  }))
};

fs.writeFileSync("dashboard/data/traces/index.json", JSON.stringify(index, null, 2));
console.log("Generated traces index with " + index.traces.length + " traces");
EOF
node /tmp/generate_index.js'
